#!/bin/sh
# SPDX-FileCopyrightText: 2026 The Atalaia contributors
# SPDX-License-Identifier: GPL-3.0-or-later
#
# Formats the core's C code (clang-format, .clang-format) and the game modes'
# Lua (StyLua, stylua.toml). With --check, changes nothing and fails if a
# file needs formatting, as CI does. Run from the repository root; the dev
# container (tools/dev/Dockerfile) has both tools. Vendored code (Lua, stb,
# LVGL's lv_conf.h) is left alone, and generated files opt out with
# "clang-format off".
set -eu

check=0
if [ "${1:-}" = "--check" ]; then
    check=1
fi

for tool in clang-format stylua; do
    if ! command -v "$tool" > /dev/null 2>&1; then
        echo "format.sh: $tool is not installed; use the dev container (docker build -t atalaia-dev tools/dev)" >&2
        exit 2
    fi
done

# Generated files keep the generator's layout.
c_dirs="core/src core/include core/tests"
if [ -d firmware ]; then
    c_dirs="$c_dirs firmware"
fi
c_files=$(find $c_dirs -name '*.[ch]' \
    -not -path '*/build/*' \
    -not -path '*/build-*/*' \
    -not -path '*/managed_components/*' \
    -not -path '*/third_party/*' \
    -not -path '*/lvgl_conf/*' \
    | sort | xargs grep -L 'Generated by tools/protogen.py')

if [ "$check" -eq 1 ]; then
    # shellcheck disable=SC2086
    clang-format --dry-run --Werror $c_files
    stylua --check modes
    echo "format.sh: C and Lua are formatted"
else
    # shellcheck disable=SC2086
    clang-format -i $c_files
    stylua modes
fi
